def compute(vars):
    net_income = vars["Net Income"]
    revenues = vars["Revenues"]
    multiplier = vars["100"]

    if revenues == 0:
        return None

    net_profit_margin = net_income / revenues * multiplier
    return {
        "value": net_profit_margin,
        "trace": {
            "Net Income": net_income,
            "Revenues": revenues,
            "100": multiplier,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
